function ConvertTo-Lf([string]$s) { return ($s -replace "`r`n", "`n") }
# patch สคริปต์ของ kit แบบหาข้อความเดิมแล้วแทน · marker มีอยู่แล้ว = ข้าม · หาข้อความเดิมไม่เจอ = warn (แก้มือ)
function Update-KitScript([string]$rel, [string]$Marker, [string]$Old, [string]$New) {
    $o = ConvertTo-Lf $Old; $n = ConvertTo-Lf $New
    $tf = { param($t) $tl = ($t -replace "`r`n", "`n"); if (-not $tl.Contains($o)) { return $null }; return $tl.Replace($o, $n) }.GetNewClosure()
    Update-ProjectFile $rel $Marker $tf
}

